public void init()
{
    next init();

    FormDataSource       primaryAddressDS = this;
    FormRun              formRun          = primaryAddressDS.formRun();
    FormDataSource       dirPartyTableDS;
    DirPartyTable        locDirPartyTable;
    if (formRun)
    {
        dirPartyTableDS = formRun.dataSource('DirPartyTable');
        if (dirPartyTableDS)
        {
            locDirPartyTable = dirPartyTableDS.cursor();
        }

    }
    QueryBuildDataSource logisticsPostalAddressPrimaryDs = this.queryBuildDataSource();


    logisticsPostalAddressPrimaryDs.clearDynalinks();
    logisticsPostalAddressPrimaryDs.clearLinks();
    logisticsPostalAddressPrimaryDs.addDynalink(fieldNum(LogisticsPostalAddress, Location),
            locDirPartyTable, fieldNum(DirPartyTable, PrimaryAddressLocation));

    if (!DirUtility::currentRoleHasAccessToPrivate())
    {
        QueryBuildRange range = SysQuery::findOrCreateRange(logisticsPostalAddressPrimaryDs, fieldNum(LogisticsPostalAddress, IsPrivate));
        range.value(SysQuery::value(NoYes::No));
        range.status(RangeStatus::Hidden);
    }
}
